public sealed class OrderRepository(IDbConnection db)
{
    public Task<IEnumerable<Order>> ForCustomerAsync(int customerId) =>
        db.QueryAsync<Order>(
            "SELECT * FROM orders WHERE customer_id = @CustomerId",
            new { CustomerId = customerId });

    public async Task<int> InsertAsync(Order order)
    {
        var id = await db.ExecuteScalarAsync<int>(
            @"INSERT INTO orders (customer_id, total)
              VALUES (@CustomerId, @Total)
              RETURNING id",
            order);

        return id;
    }

    public Task<IEnumerable<OrderSummary>> SummariesAsync() =>
        db.QueryAsync<Order, Customer, OrderSummary>(
            @"SELECT o.*, c.*
              FROM orders o JOIN customers c ON c.id = o.customer_id",
            (order, customer) => new OrderSummary(order, customer),
            splitOn: "id");
}
